INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_002_001", "調子が上がって\nきたなっ", 3000, "vo_minigame_1013_icon_1_002_001", 2, 2, "訓練はまだ\nここからですわ", 1000, 2, 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_003_001", "ほらほら、\nまだいけるだろ？", 3000, "vo_minigame_1013_icon_1_003_001", 2, 2, "クスクス、悪くない\n流れですわね", 5000, 2, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_004_001", "へへっ、おまえら\nやるじゃねえか！", 3000, "vo_minigame_1013_icon_1_004_001", 2, 3, "すばらしい\n記録ですわ", 10000, 2, 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_005_001", "あたしたちはまだ\n止まらねえぜ！", 3000, "vo_minigame_1013_icon_1_005_001", 3, 3, "乗りに乗って\nいますわね", 10000, 2, 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_005_002", "見てろよ！\nマコト班の快進撃だ！", 3000, "vo_minigame_1013_icon_1_005_002", 3, 3, "まだまだ行きます\nついてきなさい", 10000, 2, 5);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_005_003", "うおぉぉっ！\n絶好調だぜ！", 3000, "vo_minigame_1013_icon_1_005_003", 3, 3, "エリコ班の\n本領発揮ですわ！", 10000, 2, 6);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_006_001", "どこまで行けるか\n楽しみだなっ！", 3000, "vo_minigame_1013_icon_1_006_001", 4, 3, "ここからは\n前人未到の領域です！", 0, 2, 7);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_007_001", "まだ諦めんなよっ", 1000, "vo_minigame_1013_icon_1_007_001", 5, 4, "厄介でしたわ…", 1, 3, 8);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_007_002", "冷やっとしたぜ…！", 1000, "vo_minigame_1013_icon_1_007_002", 5, 4, "油断大敵です", 1, 3, 9);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_007_003", "弱音を吐くなっ", 1000, "vo_minigame_1013_icon_1_007_003", 5, 4, "忌々しいっ…", 1, 3, 10);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_008_001", "マコト班集合！", 1500, "vo_minigame_1013_icon_1_008_001", 6, 3, "大所帯ですわね", 99, 4, 11);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_008_002", "連携してくぞ！", 1500, "vo_minigame_1013_icon_1_008_002", 6, 3, "エリコ班へようこそ", 99, 4, 12);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_020_001", "みんなに力を！", 3000, "vo_minigame_1013_icon_1_020_001", 8, 6, "ナナカちゃんに\nお任せあれ", 0, 1, 13);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_022_001", "任せてくれたまえ", 3000, "vo_minigame_1013_icon_1_022_001", 9, 7, "はっはっは！\n任せろ！", 0, 1, 14);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES ("vo_minigame_1013_icon_2_023_001", "ほな、いきまひょか", 3000, "vo_minigame_1013_icon_1_023_001", 10, 8, "どんどんいくわよ", 0, 1, 15);
